mapper.select:
select id, goods_id, goods_name, goods_image_url, goods_detail, original_price, category_id, total_stock, locked_stock, create_time, update_time
from sku
where goods_id = #{goodsId}

select id, goods_id, goods_name, goods_image_url, goods_detail, original_price, category_id, total_stock, locked_stock, create_time, update_time
from sku


        and category_id = #{categoryId}


order by id desc
limit #{offset}, #{pageSize}

mapper.update:
update sku
set goods_name = #{goodsName}, goods_image_url = #{goodsImageUrl}, original_price = #{originalPrice}, category_id = #{categoryId}, total_stock = #{totalStock}, locked_stock = #{lockedStock}
where goods_id = #{goodsId}

update sku
set locked_stock = locked_stock + #{count}
where goods_id = #{goodsId}

update sku
set locked_stock = locked_stock - #{count}
where goods_id = #{goodsId} and locked_stock >= #{count}
